-- Функции доступа (их используют RPC на Этапе 5) должны совпадать с политиками.
-- Выполняются от postgres (RLS не применяется), пользователь задаётся через claims.
create function pg_temp.fnvis(p_uid uuid, p_tbl text, p_expr text) returns text language sql as $f$
  select pg_temp.act(p_uid, 'postgres', format(
    $q$select coalesce(string_agg(right(id::text, 2), ',' order by right(id::text, 2)), '')
       from public.%I where id::text ~ '^b[0-6]000000-0000-4000-8000-' and %s$q$, p_tbl, p_expr))
$f$;
