select is(pg_temp.vis('b0000000-0000-4000-8000-000000000013', 'task_history'), '11,31,41', 'после передачи новый менеджер видит историю переданной задачи, но не соседних');
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000013', 'objects'), '01,03,04', 'после передачи новый менеджер получает объект');
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000013', 'tasks'), '11,31,41', 'после передачи полный доступ только к текущим задачам');
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000011', 'comments'), '', 'после передачи прежний менеджер теряет чат задачи');
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000011', 'objects'), '01,02', 'прежний менеджер сохраняет оба созданных объекта');
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000011', 'tasks'), '', 'прежний менеджер: задач нет');
update public.tasks set assigned_to = 'b0000000-0000-4000-8000-000000000022' where id = 'b3000000-0000-4000-8000-000000000011';
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000021', 'comments'), '41', 'после передачи прежний исполнитель теряет чат задачи');
select is(pg_temp.vis('b0000000-0000-4000-8000-000000000022', 'comments'), '11,12', 'после передачи новый исполнитель видит чат с прежними сообщениями');
-- Проверка самого механизма имитации пользователя.
select is(pg_temp.act('b0000000-0000-4000-8000-000000000011', 'authenticated', 'select current_user'),
  'authenticated', 'механизм: запрос выполняется под ролью authenticated');
select is(pg_temp.act('b0000000-0000-4000-8000-000000000011', 'authenticated', 'select auth.uid()::text'),
  'b0000000-0000-4000-8000-000000000011', 'механизм: auth.uid() равен заданному sub');
select is(pg_temp.act(null, 'anon', 'select current_user'), 'anon', 'механизм: роль anon');
select is(current_user::text, 'postgres', 'механизм: после имитации роль восстановлена');

select * from finish();
rollback;
